//! Generated by tools/gen_menu.py: the menu's backing controls, in the order its
//! buttons press them (`mod.control:<index>`). Tabs come first.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Toggle,
    Slider,
    Choice,
    Keybind,
    Button,
    /// A second button pressing another control; sent as a plain button nobody presses.
    #[allow(dead_code)]
    Alias,
}

pub const TABS: [&str; 2] = ["Layout", "Look"];

